SELECT f.firing_id,f.automation_id,CAST(f.due_ms AS TEXT) AS due_ms,f.revision,f.content_id,c.revision_id AS content_revision_id,c.digest AS content_digest,f.state,f.batch_id,CAST(f.report_seq AS TEXT) AS report_seq,f.outcome_json FROM automation_firings f LEFT JOIN content_revisions c USING(content_id) WHERE f.firing_id=?;
